import java.util.*;

class Solution {
    public List<Integer> moduleOrder(int n, int[][] needs) {
        List<List<Integer>> next = new ArrayList<>();
        for (int i = 0; i < n; i++) next.add(new ArrayList<>());
        int[] indeg = new int[n];
        for (int[] p : needs) { next.get(p[1]).add(p[0]); indeg[p[0]]++; }
        PriorityQueue<Integer> ready = new PriorityQueue<>(); // smallest ready module first
        for (int i = 0; i < n; i++) if (indeg[i] == 0) ready.add(i);
        List<Integer> order = new ArrayList<>();
        while (!ready.isEmpty()) {
            int v = ready.poll();
            order.add(v);
            for (int u : next.get(v)) if (--indeg[u] == 0) ready.add(u);
        }
        return order.size() == n ? order : new ArrayList<Integer>();
    }
}

