class Solution:
    def moduleOrder(self, n: int, needs: List[List[int]]) -> List[int]:
        g = [[] for _ in range(n)]; deg = [0] * n
        for a, b in needs: g[b].append(a); deg[a] += 1
        h = [v for v in range(n) if deg[v] == 0]; heapify(h); out = []
        while h:
            v = heappop(h); out.append(v)
            for u in g[v]:
                deg[u] -= 1
                if deg[u] == 0: heappush(h, u)
        return out if len(out) == n else []

