function moduleOrder(n, needs) {
  const g = Array.from({length: n}, () => []), deg = new Array(n).fill(0), done = new Array(n).fill(false), out = [];
  for (const [a, b] of needs) { g[b].push(a); deg[a]++; }
  for (let step = 0; step < n; step++) {
    let v = -1; for (let i = 0; i < n; i++) if (!done[i] && deg[i] === 0) { v = i; break; }
    if (v < 0) return [];
    done[v] = true; out.push(v); for (const u of g[v]) deg[u]--;
  }
  return out;
}
